import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"gpt简单版","description":"1. 响应式系统 问题 如何实现响应式数据系统？ 如何追踪和触发依赖？ 步骤 使用 Proxy 和 Reflect 实现响应式数据系统。 创建一个依赖追踪系统，使用 Dep 类来管理依赖。 示例代码 // 定义一个函数，用于将目标对象转换为响应式对象 function react。","frontmatter":{"title":"gpt简单版","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","原理与手写实现"],"description":"1. 响应式系统 问题 如何实现响应式数据系统？ 如何追踪和触发依赖？ 步骤 使用 Proxy 和 Reflect 实现响应式数据系统。 创建一个依赖追踪系统，使用 Dep 类来管理依赖。 示例代码 // 定义一个函数，用于将目标对象转换为响应式对象 function react。","sidebarWeight":45,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/手写/gpt简单版.md"},"headers":[],"relativePath":"posts/Vue系统教程/05-原理与手写实现/gpt简单版.md","filePath":"posts/Vue系统教程/05-原理与手写实现/gpt简单版.md"}'),l={name:"posts/Vue系统教程/05-原理与手写实现/gpt简单版.md"};function i(n,e,c,d,s,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="gpt简单版" tabindex="-1">gpt简单版 <a class="header-anchor" href="#gpt简单版" aria-label="Permalink to &quot;gpt简单版&quot;">​</a></h1><blockquote><p>本节目标：理解“gpt简单版”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><h3 id="_1-响应式系统" tabindex="-1">1. 响应式系统 <a class="header-anchor" href="#_1-响应式系统" aria-label="Permalink to &quot;1. 响应式系统&quot;">​</a></h3><h4 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h4><ul><li>如何实现响应式数据系统？</li><li>如何追踪和触发依赖？</li></ul><h4 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ul><li>使用 <code>Proxy</code> 和 <code>Reflect</code> 实现响应式数据系统。</li><li>创建一个依赖追踪系统，使用 <code>Dep</code> 类来管理依赖。</li></ul><h4 id="示例代码" tabindex="-1">示例代码 <a class="header-anchor" href="#示例代码" aria-label="Permalink to &quot;示例代码&quot;">​</a></h4><p>// 定义一个函数，用于将目标对象转换为响应式对象 function reactive(target) { // 定义处理器对象，包含 get 和 set 拦截器 const handler = { // get 拦截器，在读取属性时触发 get(target, key, receiver) { // 使用 Reflect.get 方法读取对象的属性值 const result = Reflect.get(target, key, receiver); // 调用 track 函数进行依赖收集 track(target, key); // 返回属性值 return result; }, // set 拦截器，在写入属性时触发 set(target, key, value, receiver) { // 记录旧值 const oldValue = target[key]; // 使用 Reflect.set 方法设置对象的属性值 const result = Reflect.set(target, key, value, receiver); // 如果新值和旧值不同，则触发依赖 if (oldValue !== result) { // 调用 trigger 函数触发依赖 trigger(target, key); } // 返回设置结果 return result; } }; // 创建并返回一个代理对象，将目标对象和处理器关联起来 return new Proxy(target, handler); }</p><p>let activeEffect = null; const targetMap = new WeakMap(); function track(target, key) { if (activeEffect) { let depsMap = targetMap.get(target); if (!depsMap) { targetMap.set(target, (depsMap = new Map())); } let dep = depsMap.get(key); if (!dep) { depsMap.set(key, (dep = new Set())); } dep.add(activeEffect); } } function trigger(target, key) { const depsMap = targetMap.get(target); if (!depsMap) return; const dep = depsMap.get(key); if (dep) { dep.forEach(effect =&gt; effect()); } } function effect(eff) { activeEffect = eff; activeEffect(); activeEffect = null; }</p><h3 id="_2-模板编译" tabindex="-1">2. 模板编译 <a class="header-anchor" href="#_2-模板编译" aria-label="Permalink to &quot;2. 模板编译&quot;">​</a></h3><h4 id="问题-1" tabindex="-1">问题 <a class="header-anchor" href="#问题-1" aria-label="Permalink to &quot;问题&quot;">​</a></h4><ul><li>如何解析模板？</li><li>如何将模板转换为虚拟 DOM？</li></ul><h4 id="步骤-1" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-1" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ul><li>使用正则表达式解析模板。</li><li>创建虚拟 DOM 树，包含节点类型和子节点。</li></ul><h4 id="示例代码-1" tabindex="-1">示例代码 <a class="header-anchor" href="#示例代码-1" aria-label="Permalink to &quot;示例代码&quot;">​</a></h4><p>function compile(template) { const reg = /{{(.+?)}}/g; let match; while ((match = reg.exec(template))) { const key = match[1].trim(); template = template.replace(match[0], <code>&quot; + state.${key} + &quot;</code>); } return new Function(&#39;state&#39;, <code>return \\</code>${template}`<code>); \\} const template = </code>&lt;div&gt;{{ message }}&lt;/div&gt;`; const render = compile(template);</p><h3 id="_3-渲染系统" tabindex="-1">3. 渲染系统 <a class="header-anchor" href="#_3-渲染系统" aria-label="Permalink to &quot;3. 渲染系统&quot;">​</a></h3><h4 id="问题-2" tabindex="-1">问题 <a class="header-anchor" href="#问题-2" aria-label="Permalink to &quot;问题&quot;">​</a></h4><ul><li>如何将虚拟 DOM 渲染为真实 DOM？</li><li>如何实现虚拟 DOM 的 diff 算法？</li></ul><h4 id="步骤-2" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-2" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ul><li>实现一个简单的虚拟 DOM 渲染函数。</li><li>实现虚拟 DOM diff 算法。</li></ul><h4 id="示例代码-2" tabindex="-1">示例代码 <a class="header-anchor" href="#示例代码-2" aria-label="Permalink to &quot;示例代码&quot;">​</a></h4><p>function createElement(tag, props, ...children) { return { tag, props, children }; } function render(vnode, container) { if (typeof vnode === &#39;string&#39;) { container.appendChild(document.createTextNode(vnode)); return; } const el = document.createElement(vnode.tag); for (const key in vnode.props) { el.setAttribute(key, vnode.props[key]); } vnode.children.forEach(child =&gt; render(child, el)); container.appendChild(el); } const vnode = createElement(&#39;div&#39;, { id: &#39;app&#39; }, createElement(&#39;span&#39;, null, &#39;Hello, world!&#39;)); render(vnode, document.body);</p><h3 id="_4-组件系统" tabindex="-1">4. 组件系统 <a class="header-anchor" href="#_4-组件系统" aria-label="Permalink to &quot;4. 组件系统&quot;">​</a></h3><h4 id="问题-3" tabindex="-1">问题 <a class="header-anchor" href="#问题-3" aria-label="Permalink to &quot;问题&quot;">​</a></h4><ul><li>如何实现组件化？</li><li>如何在组件中使用响应式数据和模板？</li></ul><h4 id="步骤-3" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-3" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ul><li>创建一个组件类，包含模板和数据。</li><li>实现组件的渲染和更新逻辑。</li></ul><h4 id="示例代码-3" tabindex="-1">示例代码 <a class="header-anchor" href="#示例代码-3" aria-label="Permalink to &quot;示例代码&quot;">​</a></h4><p>class Component { constructor(options) { this.template = options.template; this.data = reactive(options.data()); this.render = compile(this.template); effect(() =&gt; this.update()); } update() { const html = this.render(this.data); document.querySelector(options.el).innerHTML = html; } } const app = new Component({ el: &#39;#app&#39;, template: <code>\\&lt;div\\&gt;{{ message }}\\&lt;/div\\&gt;</code>, data() { return { message: &#39;Hello, Vue!&#39; }; } });</p><h3 id="_5-路由系统" tabindex="-1">5. 路由系统 <a class="header-anchor" href="#_5-路由系统" aria-label="Permalink to &quot;5. 路由系统&quot;">​</a></h3><h4 id="问题-4" tabindex="-1">问题 <a class="header-anchor" href="#问题-4" aria-label="Permalink to &quot;问题&quot;">​</a></h4><ul><li>如何实现前端路由？</li><li>如何在 URL 变化时更新视图？</li></ul><h4 id="步骤-4" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-4" aria-label="Permalink to &quot;步骤&quot;">​</a></h4><ul><li>使用 <code>history</code> API 实现路由。</li><li>创建一个路由组件，监听 URL 变化并渲染对应的组件。</li></ul><h4 id="示例代码-4" tabindex="-1">示例代码 <a class="header-anchor" href="#示例代码-4" aria-label="Permalink to &quot;示例代码&quot;">​</a></h4><p>class Router { constructor(routes) { this.routes = routes; window.addEventListener(&#39;popstate&#39;, () =&gt; this.render()); this.render(); } push(path) { window.history.pushState({}, &#39;&#39;, path); this.render(); } render() { const path = window.location.pathname; const route = this.routes.find(route =&gt; route.path === path); if (route) { document.querySelector(&#39;#app&#39;).innerHTML = route.component.template; } } } const Home = { template: &#39;&lt;div&gt;Home&lt;/div&gt;&#39; }; const About = { template: &#39;&lt;div&gt;About&lt;/div&gt;&#39; }; const router = new Router([ { path: &#39;/&#39;, component: Home }, { path: &#39;/about&#39;, component: About } ]);</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>通过一步步回答以上问题和实现代码，你可以构建一个简单的 Vue 3 框架。这个框架包含了响应式数据、模板编译、虚拟 DOM 渲染、组件化和路由系统。每个步骤都可以根据需要进一步扩展和优化。</p></div>',1)])])}const f=t(l,[["render",i]]);export{p as __pageData,f as default}